// ---- Types pinned by scripts/export_schema.py ----

export interface IngestQueued {
  event: "ingest_queued";
  job_uuid: string;
  document_uuid: string;
}

export interface IngestStarted {
  event: "ingest_started";
  job_uuid: string;
  document_uuid: string;
}

export interface IngestProgress {
  event: "ingest_progress";
  job_uuid: string;
  document_uuid: string;
  phase: string;
  message: string;
}

export interface IngestCompleted {
  event: "ingest_completed";
  job_uuid: string;
  document_uuid: string;
}

export interface IngestError {
  event: "ingest_error";
  job_uuid: string;
  document_uuid: string;
  phase: string | null;
  message: string;
}

export interface SSETextDelta {
  event: "text_delta";
  content: string;
}

export interface SSEFunctionCall {
  event: "function_call";
  call_id: string;
  name: string;
  arguments: {
    [k: string]: unknown;
  };
}

export interface SSEFunctionCallOutput {
  event: "function_call_output";
  call_id: string;
  tool_name: string;
  success: boolean;
  data?: {
    [k: string]: unknown;
  } | null;
  errors?: string[] | null;
}

export interface SSEUiNotice {
  event: "ui_notice";
  content: string;
  /**
   * Severity of a ui_notice; drives whether the UI renders it muted or
   * error-styled.
   */
  level?: "info" | "error";
}

export interface SSEInterrupt {
  event: "interrupt";
  stage: string;
  payload: {
    [k: string]: unknown;
  };
}

export interface SSECalcStart {
  event: "calc_start";
}

export interface SSEDone {
  event: "done";
}

// ---- Discriminated unions (appended by scripts/export_schema.py) ----

export type IngestEvent =
  | IngestQueued
  | IngestStarted
  | IngestProgress
  | IngestCompleted
  | IngestError;
export type SSEEvent =
  | SSETextDelta
  | SSEFunctionCall
  | SSEFunctionCallOutput
  | SSEUiNotice
  | SSEInterrupt
  | SSECalcStart
  | SSEDone;
